mapper.select:
SELECT p.product_Idx AS productIdx, p.category AS category, p.subCategory AS subCategory, p.product_Name AS productName, p.price AS price, p.reg_Date AS regDate, p.product_Desc AS productDesc, p.product_main_img AS productMainImg, p.discount_rate AS discountRate, p.is_Recommended AS isRecommended, IFNULL(ROUND(AVG(r.rating)),0) as avgRating, COUNT(r.product_Idx) as reviewCount FROM Products p LEFT JOIN Reviews r ON p.product_Idx = r.product_Idx
AND p.category = #{category}
AND p.subCategory = #{subCategory}
GROUP BY p.product_Idx, p.category, p.subCategory, p.product_Name, p.price, p.reg_Date, p.product_Desc, p.product_main_img, p.discount_rate, p.is_Recommended ORDER BY p.reg_Date DESC
